/// Floppy disc drive management service.
///
/// Provides insert/eject operations with safe eject support,
/// drive status queries, and event streaming for multiple clients.
///
/// To build a server, implement a class that conforms to this protocol.
internal protocol Beebium_DiscServiceProvider: CallHandlerProvider {
  var interceptors: Beebium_DiscServiceServerInterceptorFactoryProtocol? { get }

  /// Insert a disc image from URL (file: scheme for local files).
  /// Fails if the drive already holds a disc: removing one is a separate,
  /// deliberate EjectDisc, so that it goes through the safe eject path.
  func insertDisc(request: Beebium_InsertDiscRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_InsertDiscResponse>

  /// Request disc ejection (non-blocking, safe eject by default).
  /// A safe eject waits as long as it takes for the drive to fall quiet;
  /// the server never gives up on its own. Giving up is the caller's
  /// decision, made by ejecting again with immediate set, or abandoned
  /// with CancelEject.
  func ejectDisc(request: Beebium_EjectDiscRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_EjectDiscResponse>

  /// Abandon a pending safe eject, leaving the disc in the drive
  func cancelEject(request: Beebium_CancelEjectRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_CancelEjectResponse>

  /// Query status of all drives
  func getDriveStatus(request: Beebium_GetDriveStatusRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_GetDriveStatusResponse>

  /// Stream drive events (insert, eject, motor changes)
  func subscribeDiscEvents(request: Beebium_SubscribeDiscEventsRequest, context: StreamingResponseCallContext<Beebium_DiscEvent>) -> EventLoopFuture<GRPCStatus>

  /// Configure motor spin-up delay (for automation scenarios)
  func setSpinUpDelay(request: Beebium_SetSpinUpDelayRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_SetSpinUpDelayResponse>

  /// Query spin-up delay configuration
  func getSpinUpDelay(request: Beebium_GetSpinUpDelayRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_GetSpinUpDelayResponse>

  /// List available disc controller types (for machines with sockets)
  func listAvailableControllers(request: Beebium_ListAvailableControllersRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_ListAvailableControllersResponse>

  /// Install a disc controller into the socket (machines with sockets only)
  func installDiscController(request: Beebium_InstallDiscControllerRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_InstallDiscControllerResponse>
}

